css_content = """/* Dungeon Haul Asset Gallery Website Stylesheet */
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700;900&family=Inter:wght@300;400;500;600;700&family=Press+Start+2P&display=swap');

:root {
