  --gold-glow: rgba(243, 192, 50, 0.15);

  --text-main: #EAE6f8;
  --text-muted: #9E98B8;
  --text-dim: #6E6888;

  --p0-bg: linear-gradient(135deg, #059669 0%, #10B981 100%);
  --p0-color: #ECFDF5;
  --p1-bg: linear-gradient(135deg, #0284C7 0%, #38BDF8 100%);
  --p1-color: #F0F9FF;
  --p2-bg: linear-gradient(135deg, #7C3AED 0%, #A855F7 100%);
  --p2-color: #FAF5FF;

  --font-pixel: 'Press Start 2P', monospace;
  --font-serif: 'Cinzel', serif;
  --font-sans: 'Inter', system-ui, sans-serif;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --transition-fast: 0.2s ease;
  --transition-normal: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Base Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-canvas);
  color: var(--text-main);
  font-family: var(--font-sans);
  min-height: 100vh;
