  overflow-x: hidden;
  background-image: 
    radial-gradient(circle at 50% 0%, rgba(243, 192, 50, 0.08) 0%, transparent 60%),
    radial-gradient(circle at 80% 40%, rgba(124, 58, 237, 0.05) 0%, transparent 50%),
    linear-gradient(180deg, #090712 0%, #0d0a1c 100%);
