  box-shadow: 0 2px 10px rgba(243, 192, 50, 0.3);
}

/* Status Bar & Counter */
.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding: 0 0.5rem;
}

.result-counter {
  font-family: var(--font-sans);
  font-size: 0.88rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Gallery Grid */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

/* Asset Card */
.asset-card {
  background: var(--bg-glass-card);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid var(--gold-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: transform var(--transition-normal), border-color var(--transition-normal), box-shadow var(--transition-normal);
  position: relative;
}

.asset-card:hover {
  transform: translateY(-5px);
  border-color: var(--gold-main);
  box-shadow: 
    0 12px 30px rgba(0, 0, 0, 0.6),
    0 0 20px rgba(243, 192, 50, 0.2);
}

/* Thumbnail Box */
.card-thumb-container {
  height: 190px;
  background: 
    linear-gradient(45deg, #110d24 25%, transparent 25%), 
    linear-gradient(-45deg, #110d24 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #110d24 75%), 
    linear-gradient(-45deg, transparent 75%, #110d24 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  background-color: #0b0917;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  overflow: hidden;
  padding: 1rem;
}

.card-img {
  max-width: 90%;
  max-height: 90%;
  object-fit: contain;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  transition: transform var(--transition-fast);
}

.asset-card:hover .card-img {
  transform: scale(1.05);
}

.card-canvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  max-width: 90%;
  max-height: 90%;
  transition: transform var(--transition-fast);
}

.asset-card:hover .card-canvas {
  transform: scale(1.08);
}

/* Badges */
.badge {
  position: absolute;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-sm);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  z-index: 2;
  box-shadow: 0 2px 8px rgba(0,0,0,0.5);
}

.badge-priority {
