}

.badge-category {
  top: 0.6rem;
  left: 0.6rem;
  background: rgba(13, 10, 28, 0.85);
  border: 1px solid var(--gold-border);
  color: var(--gold-main);
  backdrop-filter: blur(4px);
}

.frame-count-tag {
  position: absolute;
  bottom: 0.5rem;
  right: 0.6rem;
  background: rgba(0, 0, 0, 0.75);
  color: var(--gold-bright);
  font-size: 0.65rem;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  border: 1px solid rgba(243, 192, 50, 0.3);
}

/* Card Body */
.card-body {
  padding: 1.1rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.card-title {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.4rem;
  line-height: 1.3;
}

.doc-id-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(9, 7, 18, 0.8);
  border: 1px dashed rgba(243, 192, 50, 0.3);
  padding: 0.3rem 0.5rem;
  border-radius: 4px;
  margin-bottom: 0.75rem;
  transition: border-color var(--transition-fast), background var(--transition-fast);
}

.doc-id-box:hover {
  border-color: var(--gold-main);
  background: rgba(243, 192, 50, 0.08);
}

.doc-id-box code {
  font-family: 'Courier New', monospace;
  font-size: 0.78rem;
  color: var(--gold-main);
