  border: none;
  color: var(--text-muted);
  font-size: 1.5rem;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.modal-close:hover {
  color: var(--gold-bright);
}

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 768px) {
  .modal-body {
    grid-template-columns: 1fr;
  }
}

.modal-preview-box {
  background: 
    linear-gradient(45deg, #110d24 25%, transparent 25%), 
    linear-gradient(-45deg, #110d24 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #110d24 75%), 
